use std::{hint::black_box, time::Instant};
use terraforged_native_core::{
    layout::Levels,
    preset::SmoothingSettings,
    terrain::TerrainRegistry,
    tile::TileBuffer,
    tile_filters_basic::Smoothing,
};

fn checksum(tile: &TileBuffer) -> u64 {
    tile.cells.iter().fold(0xcbf29ce484222325, |hash, cell| {
        (hash ^ u64::from(cell.height.to_bits())).wrapping_mul(0x100000001b3)
    })
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let levels = Levels::new(320, 63);
    let terrains = TerrainRegistry::new();
    let terrain_count = terrains.iter().count();
    let mut base = TileBuffer::new(0, 0, 3, 1)?;
    for (index, cell) in base.cells.iter_mut().enumerate() {
        let x = index as u32 % 160;
        let z = index as u32 / 160;
        let hash = x.wrapping_mul(1_664_525) ^ z.wrapping_mul(1_013_904_223);
        cell.height = 0.15 + ((hash >> 8) & 65535) as f32 / 65535.0 * 0.7;
        cell.erosion_mask = index % 17 == 0;
        cell.terrain = index % terrain_count;
        cell.terrain_region_edge = (index % 31) as f32 / 30.0;
        cell.river_mask = (index % 23) as f32 / 22.0;
    }
    println!("{{\"scope\":\"Smoothing filter only; one iteration on deterministic 160x160 tile backing (factor3 border1), clone and full-height checksum excluded from timer; two warmups, six trials per radius\",\"baseChecksum\":\"{:016x}\",\"observations\":[", checksum(&base));
    for (radius_index, radius) in [1.8_f32, 8.0, 32.0].into_iter().enumerate() {
        let filter = Smoothing::new(SmoothingSettings {
            iterations: 1,
            smoothing_radius: radius,
            smoothing_rate: 0.9,
        }, levels);
        let mut expected = None;
        for _ in 0..2 {
            let mut tile = base.clone();
            filter.apply(&mut tile, 1, &terrains)?;
            expected = Some(black_box(checksum(&tile)));
        }
        for trial in 0..6 {
            let mut tile = base.clone();
            let start = Instant::now();
            filter.apply(black_box(&mut tile), 1, black_box(&terrains))?;
            let seconds = start.elapsed().as_secs_f64();
            let hash = black_box(checksum(&tile));
            assert_eq!(Some(hash), expected, "nondeterministic smoothing output");
            if radius_index != 0 || trial != 0 { println!(","); }
            print!("{{\"radius\":{},\"trial\":{},\"seconds\":{},\"heightChecksum\":\"{:016x}\"}}", radius, trial, seconds, hash);
        }
    }
    println!("]}}");
    Ok(())
}
